change(10,'p2-t4-d07-x04','Single-object tracking và multi-object tracking khác nhau ở mục tiêu nào?', ['SOT bắt đầu từ vật được chỉ định; MOT theo các instances thuộc lớp quan tâm','SOT luôn là offline còn MOT luôn dùng frame tương lai','SOT chỉ dùng masks còn MOT chỉ dùng keypoints'],'Số lượng/mục tiêu đối tượng là trục khác với online/offline hoặc loại biểu diễn output.',8)
change(10,'p2-t4-d07-x07','Tăng min_hits trước khi xác nhận một track tạo tradeoff nào?', ['Giảm xác nhận detection thoáng qua nhưng chờ nhiều bằng chứng hơn cho track mới','Làm track Lost được giữ lâu hơn khi mất detection','Trực tiếp tăng độ tương đồng appearance giữa hai crop'],'min_hits liên quan Tentative→Confirmed; khác track_buffer quyết định thời gian giữ Lost.',12)
change(10,'p2-t4-d08-x05','Copy-paste một xe sang vị trí xa hơn trong ảnh monocular cần điều chỉnh gì để không dạy sai hình học?', ['Scale kích thước theo phối cảnh của vị trí mới','Giữ nguyên kích thước pixel dù depth thay đổi','Chỉ đổi nhãn class và bỏ qua tỷ lệ ảnh'],'Augmentation phải tôn trọng quan hệ kích thước–khoảng cách, nếu không dữ liệu tạo mâu thuẫn hình học.',11)
change(10,'p2-t4-d08-x08','PETR đưa thông tin hình học 3D vào image features bằng cách nào?', ['Gắn mã vị trí 3D để object queries attend vào features','Bắt mọi query dùng cùng pixel cố định của mọi camera','Chỉ ghép raw point clouds rồi bỏ ảnh trước decoder'],'PETR dùng positional encoding 3D trong image feature, khác cách chiếu reference point để lấy feature của DETR3D.',17)
change(10,'p2-t4-d08-x12','Early sensor fusion nhạy với một sensor hỏng hoặc nhiễu theo cơ chế nào?', ['Dữ liệu đã trộn từ input nên lỗi có thể làm hỏng biểu diễn chung ngay từ đầu','Mỗi detector độc lập đã loại bỏ mọi lỗi trước khi ghép boxes','Mọi phép đo đều được giữ riêng cho từng Kalman update nên không có input chung'],'Early fusion giữ thông tin raw nhưng đòi hỏi calibration/synchronization tốt và có thể lan lỗi sensor vào đầu vào chung.',31)
change(10,'p2-t4-d08-x13','Trong hand-eye calibration AX=XB, X biểu diễn điều gì?', ['Phép biến đổi cố định giữa hai sensor gắn cứng được suy từ chuyển động tương ứng','Một pose object mới cần dự đoán ở từng frame','Một focal length thay đổi theo khoảng cách tới vật'],'Di chuyển hệ qua nhiều poses tạo các chuyển động A/B để giải phép biến đổi cố định X giữa hai sensor.',28)
change(10,'p2-t4-d08-x15','Trong thiết kế fuse-then-track gộp measurements trước tracker, tracker nhận gì ở mỗi chu kỳ?', ['Một phép đo fused và thực hiện một update','Lần lượt từng phép đo sensor riêng với h(x),R riêng','Một track độc lập cho mỗi camera không bao giờ kết hợp'],'Đây là trục thứ tự fusion/tracking: gộp measurement trước khác tuần tự cập nhật một trạng thái bằng từng sensor.',36)
change(10,'p2-t4-d09-x05','ELT thay đổi thứ tự xử lý dữ liệu video so với ETL thế nào?', ['Nạp bản gốc vào storage/lakehouse trước rồi biến đổi','Luôn decode và biến đổi toàn bộ video trước khi lưu','Chỉ lưu bảng đã xử lý và không giữ video gốc'],'ELT tránh để biến đổi video nặng chặn bước nạp; video ở storage còn metadata được xử lý thành bảng.',22)
